184	  preload() {
185	    // 선택된 배경화면 조건부 로딩 (DifficultySelectScene에서 미리 로드 안 된 경우 fallback)
186	    const wpDef = this.selectedWpId ? getWallpaperDef(this.selectedWpId) : null;
