248	  private getDefaultBackgroundKey(): string {
249	    if (this.difficulty === Difficulty.NORMAL) return 'background3';
250	    if (this.difficulty === Difficulty.EXTREME) {
251	      return isChristmasSeason() ? 'xmas_background' : 'background2';
252	    }
253	    return 'background'; // EASY / HARD
254	  }
