256	  create() {
257	    super.create();
258	
259	    // 키보드 이벤트 수신을 위해 캔버스 포커스 설정
260	    const canvas = this.game.canvas;
261	    canvas.setAttribute('tabindex', '0');
262	    canvas.focus();
263	
264	    // Phaser 내부 시간 기준점 기록 (씬 재시작 시에도 정확한 delta 계산)
265	    this.phaserStartTime = this.time.now;
266	    // rAF 체크 두 기준점을 동시에 설정 — preload 시간 불일치 방지
267	    this.resetCheatCheckpoints();
268	
269	    this.highScore = getHighScore(this.scoreDifficulty);
270	    this.charHighScore = this.scoreDifficulty === Difficulty.EXTREME
271	      ? getExtremeCharBest(this.selectedCharId)
272	      : 0;
273	    this.charHighScoreAtStart = this.charHighScore;
274	
275	    // 배경 이미지: 선택된 배경화면 우선, 없으면 난이도별 기본
276	    const wpDefForBg = this.selectedWpId ? getWallpaperDef(this.selectedWpId) : null;
277	    const backgroundKey = (wpDefForBg && this.textures.exists(wpDefForBg.bgKey))
278	      ? wpDefForBg.bgKey
279	      : this.getDefaultBackgroundKey();
280	
281	    const W = this.scale.width;
282	    const H = this.scale.height;
283	    const cx = W / 2;
284	
285	    const background = this.add.image(cx, H / 2, backgroundKey);
286	    background.setDisplaySize(W, H);
287	
288	    // BGM 키 결정 (preload에서 이미 로드됨)
289	    let bgMusicKey = 'bgMusic';
290	    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason()) {
291	      bgMusicKey = 'xmasBgMusic';
292	    }
293	
294	    // 이전 bgMusic 인스턴스가 있으면 전역 SoundManager에서 제거
295	    if (this.bgMusic) {
296	      this.bgMusic.destroy();
297	    }
298	
299	    // BGM 재생 (preload에서 이미 로드 완료됨)
300	    this.bgMusic = this.sound.add(bgMusicKey, { loop: true, volume: 0.5 });
301	    this.bgMusic.play();
302	
303	    // 월드 바운드 설정 (플레이어가 화면 안쪽에만 머무르도록)
304	    this.physics.world.setBounds(15, 0, W - 30, H);
305	
306	    // 플레이어 생성 (난이도별 속도 적용, 게임 모드별 스프라이트)
307	    const CHARS_WITH_SPRITES = GameScene.CHARS_WITH_SPRITES;
308	    let playerTexturePrefix = '';
309	    if (CHARS_WITH_SPRITES.includes(this.selectedCharId)) {
310	      playerTexturePrefix = `${this.selectedCharId}_`;
311	    }
312	    // 등급 각성 패시브: ★1 R+5/SR+10/UR+15, ★2 R+10/SR+15/UR+20
313	    // 매화 예외: ★1 +5, ★2+ 속도 패시브 없음 (대신 특수똥 수집 +5pt)
314	    const _gs = (r: number, sr: number, ur: number) =>
315	      this.selectedCharGrade === 'UR' ? ur
316	      : this.selectedCharGrade === 'SR' ? sr
317	      : this.selectedCharGrade === 'R'  ? r
318	      : 0;
319	    const gradeAwakeSpeed = this.selectedCharId === 'maehwa'
320	      ? (this.charAwakeLevel >= 1 ? 5 : 0)
321	      : this.charAwakeLevel >= 2 ? _gs(10, 15, 20)
322	      : this.charAwakeLevel >= 1 ? _gs(5, 10, 15)
323	      : 0;
324	    const [playerW, playerH] = getCharacterDef(this.selectedCharId).playerDisplaySize ?? [50, 80];
325	    this.player = new Player(this, cx, H - 80, this.difficultyConfig.playerSpeed + this.ability.getPlayerSpeedBonus() + gradeAwakeSpeed + (this.activeSynergy?.speedBonus ?? 0), playerTexturePrefix, playerW, playerH);
326	
327	    // 💩 그룹 생성 (Object Pool: maxSize로 상한 설정)
328	    this.poops = this.physics.add.group({
329	      classType: Poop,
330	      runChildUpdate: true,
331	      maxSize: 60,
332	    });
333	
334	    // 금똥 그룹 생성
335	    this.goldPoops = this.physics.add.group({
336	      classType: GoldPoop,
337	      runChildUpdate: true,
338	      maxSize: 20,
339	    });
340	
341	    // 다이아똥 그룹 생성
342	    this.diamondPoops = this.physics.add.group({
343	      classType: DiamondPoop,
344	      runChildUpdate: true,
345	      maxSize: 20,
