884	  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 캔버스에 cover */
885	  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
886	    const W = this.scale.width, H = this.scale.height;
887	    vid.setDisplaySize(W, H);
888	
889	    const applyContain = () => {
890	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
891	      const el: HTMLVideoElement | null = (vid as any).video ?? null;
892	      const nw = el?.videoWidth  || 0;
893	      const nh = el?.videoHeight || 0;
894	      if (nw > 0 && nh > 0) {
895	        const scale = Math.max(W / nw, H / nh);
896	        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
897	      }
898	    };
899	
900	    vid.once('play', applyContain);
901	    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
902	    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
903	  }
